mapper.select:
SELECT , S.SELLER_NM, S.SELLER_STAT, C.CTG_NM, C.UPPER_CTG_CD, UC.CTG_NM AS UPPER_CTG_NM, P.SUPPLY_PRC, P.DLV_FEE_TYPE, P.MAX_ORD_QTY, P.STOP_RSN, NVL(K.STK_QTY, 0) AS STK_QTY, NVL(K.STK_QTY, 0) - NVL(K.RSV_QTY, 0) AS AVAIL_QTY,
CASE WHEN P.SALE_STAT = 'ON' AND NVL(K.STK_QTY, 0) - NVL(K.RSV_QTY, 0) > 0 THEN 'Y' ELSE 'N' END AS ORD_ABLE_YN, TO_CHAR(P.REG_DT, 'YYYYMMDD') AS REG_DT, TO_CHAR(P.UPD_DT, 'YYYY-MM-DD HH24:MI') AS UPD_DT FROM TB_PRD P JOIN TB_SELLER S ON S.SELLER_ID = P.SELLER_ID JOIN TB_PRD_CTG C ON C.CTG_CD = P.CTG_CD LEFT JOIN TB_PRD_CTG UC ON UC.CTG_CD = C.UPPER_CTG_CD LEFT JOIN TB_STK K ON K.PRD_CD = P.PRD_CD
AND P.PRD_CD LIKE #{PRD_CD} || '%' AND P.PRD_NM LIKE '%' || #{PRD_NM} || '%' AND P.SELLER_ID = #{SELLER_ID}
AND (P.CTG_CD = #{CTG_CD} OR C.UPPER_CTG_CD = #{CTG_CD})
AND P.SALE_STAT = #{SALE_STAT} AND P.SALE_PRC >= #{PRC_FROM} AND P.SALE_PRC <= #{PRC_TO}
ORDER BY P.REG_DT DESC, P.PRD_CD

SELECT 
  FROM TB_PRD P
 WHERE P.PRD_CD = #{prdCd}

SELECT C.CTG_CD, C.CTG_NM, C.UPPER_CTG_CD, C.CTG_LVL, C.COMM_RATE, NVL(C.COMM_RATE, UC.COMM_RATE) AS APPLY_COMM_RATE, C.SORT_ORD, C.USE_YN, (SELECT COUNT(*) FROM TB_PRD P WHERE P.CTG_CD = C.CTG_CD) AS PRD_CNT FROM TB_PRD_CTG C LEFT JOIN TB_PRD_CTG UC ON UC.CTG_CD = C.UPPER_CTG_CD
AND C.CTG_NM LIKE '%' || #{CTG_NM} || '%' AND C.USE_YN = #{USE_YN}
ORDER BY NVL(UC.SORT_ORD, C.SORT_ORD), NVL(C.UPPER_CTG_CD, C.CTG_CD), C.CTG_LVL, C.SORT_ORD

SELECT SELLER_ID, SELLER_NM, BIZ_NO, COMM_RATE, STL_ACCT_NO, BANK_CD, SELLER_STAT
  FROM TB_SELLER
 WHERE SELLER_ID = #{sellerId}
